UPDATE
        LOAN_APPLICATION
   SET
        STATUS         = #{status}
     ,  APPROVED_LIMIT = #{approvedLimit, jdbcType=NUMERIC}
     ,  DSR            = #{dsr,           jdbcType=NUMERIC}
     ,  REJECT_REASON  = #{rejectReason,  jdbcType=VARCHAR}
     ,  SCREENED_AT    = CURRENT_TIMESTAMP
 WHERE
        APPLICATION_NO = #{applicationNo}
